{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C27"],
      "claim": "Olcegepant, a high-transfer analogue, has absolute oral bioavailability <1% in humans, directly supporting a low-F classification for the query's complex polar scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Alvimopan, a high-transfer zwitterionic analogue, has human oral bioavailability of only 6%, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Melagatran, a high-transfer polar thrombin inhibitor, has human oral bioavailability of 3–7%, supporting low oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Plecanatide, a high-transfer peptide, shows negligible systemic availability after oral dosing in humans, directly relevant to the peptide-like query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Octreotide, a high-transfer cyclic peptide, has absolute oral bioavailability of 0.6 ± 0.4% in healthy volunteers, strongly supporting low F for the peptide query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Aliskiren, a high-transfer non-peptide drug, has mean absolute oral bioavailability of 2.6% in humans, reinforcing that high polarity and molecular complexity lead to low F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show human oral bioavailability below 20%, mostly below 10%, and several are peptides with negligible oral absorption; therefore the query is predicted to have low absolute oral bioavailability at the F >= 20% threshold.",
  "evidence_gaps": [
    "No direct human absolute oral bioavailability measurement exists for the query molecule itself.",
    "Fasted-state-specific bioavailability data are not consistently reported for the analogue records.",
    "The query contains fatty-acid/PEG modifications that may alter absorption, but no direct analogue with the same modification is present in the evidence set."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

